/**
 * GOLDEN VECTORS for equal-split expenses (M5, ADR-063). TEST-ONLY: this folder is outside src/, is not exported from the package, and is never imported by production code (a test checks that).
 *
 * Every number below was worked out BY HAND (see the comments), not generated by either implementation. The same file
 * is used by two test suites:
 *   - packages/core (expenseVectors.test.ts): the TypeScript engine (computeSplit, computeBalances) must reproduce
 *     every allocation and every member balance.
 *   - supabase/tests (expenses.test.ts): the database functions (allocate_equal, create/update/delete/restore_expense,
 *     trip_member_balances) must reproduce the very same numbers, and refuse the very same steps with the same error.
 * If either implementation changes its rounding, tie-breaking or balance rules, the other suite fails too.
 *
 * Ties go to the lowest member id compared as plain text (digits sort before letters). Member ids here ascend with the
 * label: A < B < C < D.
 */

/** A member id built from a short hex suffix (the rest is fixed), so the order of the ids is easy to read. */
export const vid = (hex: string): string => `00000000-0000-4000-8000-${hex.padStart(12, '0')}`;

/** The four named members used by the ledger vectors. */
export const MEMBER_IDS: Record<string, string> = { A: vid('a1'), B: vid('b2'), C: vid('c3'), D: vid('d4') };

// ---------------------------------------------------------------------------------------------------------------
// 1. Individual allocations
// ---------------------------------------------------------------------------------------------------------------
export interface SplitVector {
  name: string;
  amountMinor: number;
  /** The participants, in the order they are SENT (the result must not depend on it). */
  participants: string[];
  /** The expected share of each participant, by member id. */
  shares: Record<string, number>;
  /** How it is split; absent means equal. */
  method?: SplitMethodName;
  /** For the other methods, the typed value of each participant by member id: paise (exact), basis points (percentage, 100% = 10000) or a weight (shares). */
  inputs?: Record<string, number>;
}

export type SplitMethodName = 'equal' | 'exact' | 'percentage' | 'shares';

const [A, B, C, D] = [MEMBER_IDS.A!, MEMBER_IDS.B!, MEMBER_IDS.C!, MEMBER_IDS.D!];
const seven = [1, 2, 3, 4, 5, 6, 7].map((n) => vid(`5${n}`)); // ...000000000051 to ...000000000057, ascending

export const SPLIT_VECTORS: SplitVector[] = [
  // Rs 10.00 / 3 = 333.33..: base 333 each, 1 paisa left over -> the lowest id (A).
  { name: 'Rs 10.00 among three: the leftover paisa goes to the lowest id', amountMinor: 1000, participants: [A, B, C], shares: { [A]: 334, [B]: 333, [C]: 333 } },
  // Same, but the participants are SENT in a different order: the answer must not change.
  { name: 'the order the participants are sent in never matters', amountMinor: 1000, participants: [C, A, B], shares: { [A]: 334, [B]: 333, [C]: 333 } },
  // 1 paisa among three: base 0, one leftover -> A.
  { name: '1 paisa among three: only the lowest id gets it', amountMinor: 1, participants: [A, B, C], shares: { [A]: 1, [B]: 0, [C]: 0 } },
  { name: '1 paisa among two', amountMinor: 1, participants: [B, A], shares: { [A]: 1, [B]: 0 } },
  // 2 paise among five: base 0, two leftovers -> the two lowest ids.
  { name: '2 paise among five: the two lowest ids', amountMinor: 2, participants: [vid('e5'), vid('d4'), vid('c3'), vid('b2'), vid('a1')], shares: { [vid('a1')]: 1, [vid('b2')]: 1, [vid('c3')]: 0, [vid('d4')]: 0, [vid('e5')]: 0 } },
  // 100 / 7 = 14 remainder 2: the two lowest ids get 15, the other five get 14 (15+15+14*5 = 100).
  { name: '100 paise among seven: 15, 15 and then 14 five times', amountMinor: 100, participants: seven, shares: Object.fromEntries(seven.map((id, i) => [id, i < 2 ? 15 : 14])) },
  { name: 'an exactly even split has no leftover', amountMinor: 900, participants: [A, B, C], shares: { [A]: 300, [B]: 300, [C]: 300 } },
  { name: 'a single participant takes everything', amountMinor: 777, participants: [B], shares: { [B]: 777 } },
  // Ids that mix digits and letters: as plain text 0009 < 000a < 0010 < 00ff (digits sort before letters).
  // 10 / 4 = 2 remainder 2: the two lowest (0009 and 000a) get 3.
  { name: 'ids mixing digits and letters are ordered as plain text', amountMinor: 10, participants: [vid('ff'), vid('10'), vid('a'), vid('9')], shares: { [vid('9')]: 3, [vid('a')]: 3, [vid('10')]: 2, [vid('ff')]: 2 } },
  // The largest amount (10^12 paise): 10^12 / 3 = 333333333333 remainder 1 -> A gets one more.
  { name: 'the largest allowed amount (10^12 paise) among three', amountMinor: 1_000_000_000_000, participants: [A, B, C], shares: { [A]: 333_333_333_334, [B]: 333_333_333_333, [C]: 333_333_333_333 } },

  // ---- percentage: basis points are the weights (100% = 10000), largest remainder, leftover to the biggest remainder, then the lowest id.
  // 1000 x 3333 / 10000 = 333 rem 3000 (A and B); 1000 x 3334 / 10000 = 333 rem 4000 (C). 999 handed out, 1 left: the biggest remainder is C.
  { name: 'percentage 33.33 / 33.33 / 33.34 of Rs 10.00: the leftover paisa goes to the biggest remainder (C)', method: 'percentage', amountMinor: 1000, participants: [A, B, C], inputs: { [A]: 3333, [B]: 3333, [C]: 3334 }, shares: { [A]: 333, [B]: 333, [C]: 334 } },
  // 999 x 5000 / 10000 = 499 rem 5000 (A); x 3000 = 299 rem 7000 (B); x 2000 = 199 rem 8000 (C). 997 handed out, 2 left: C (8000) then B (7000).
  { name: 'percentage 50 / 30 / 20 of 999 paise: two leftover paise go to the two biggest remainders', method: 'percentage', amountMinor: 999, participants: [A, B, C], inputs: { [A]: 5000, [B]: 3000, [C]: 2000 }, shares: { [A]: 499, [B]: 300, [C]: 200 } },
  // 1 paisa x 5000 = remainder 5000 for both: a tie, so the lowest id (A) gets it.
  { name: 'percentage 50 / 50 of 1 paisa: a tie goes to the lowest id', method: 'percentage', amountMinor: 1, participants: [B, A], inputs: { [A]: 5000, [B]: 5000 }, shares: { [A]: 1, [B]: 0 } },
  { name: 'percentage 100% for one person takes everything', method: 'percentage', amountMinor: 777, participants: [B], inputs: { [B]: 10000 }, shares: { [B]: 777 } },
  // 10^12 x 3333 / 10000 = 333300000000 exactly (no remainder); C: 333400000000.
  { name: 'percentage at the largest amount (10^12 paise) has no remainder to hand out', method: 'percentage', amountMinor: 1_000_000_000_000, participants: [A, B, C], inputs: { [A]: 3333, [B]: 3333, [C]: 3334 }, shares: { [A]: 333_300_000_000, [B]: 333_300_000_000, [C]: 333_400_000_000 } },

  // ---- shares: relative weights (a whole number each), same rule.
  { name: 'shares 2 : 1 : 1 of Rs 10.00 divides exactly', method: 'shares', amountMinor: 1000, participants: [A, B, C], inputs: { [A]: 2, [B]: 1, [C]: 1 }, shares: { [A]: 500, [B]: 250, [C]: 250 } },
  { name: 'shares 1 : 1 : 1 of 100 paise equals the equal split (34, 33, 33)', method: 'shares', amountMinor: 100, participants: [A, B, C], inputs: { [A]: 1, [B]: 1, [C]: 1 }, shares: { [A]: 34, [B]: 33, [C]: 33 } },
  // 7 x 3 = 21 / 5 = 4 rem 1 (A); 7 x 2 = 14 / 5 = 2 rem 4 (B). 6 handed out, 1 left: the bigger remainder is B.
  { name: 'shares 3 : 2 of 7 paise: the leftover goes to the bigger remainder (B)', method: 'shares', amountMinor: 7, participants: [A, B], inputs: { [A]: 3, [B]: 2 }, shares: { [A]: 4, [B]: 3 } },
  { name: 'shares 1 : 1 of 3 paise: a tie goes to the lowest id', method: 'shares', amountMinor: 3, participants: [B, A], inputs: { [A]: 1, [B]: 1 }, shares: { [A]: 2, [B]: 1 } },
  // 1 paisa: remainders 5, 3, 2 (out of 10): A.
  { name: 'shares 5 : 3 : 2 of 1 paisa: only the biggest remainder gets it', method: 'shares', amountMinor: 1, participants: [C, B, A], inputs: { [A]: 5, [B]: 3, [C]: 2 }, shares: { [A]: 1, [B]: 0, [C]: 0 } },
  { name: 'shares: the largest allowed weight (1,000,000) works', method: 'shares', amountMinor: 1000, participants: [A, B], inputs: { [A]: 1_000_000, [B]: 1_000_000 }, shares: { [A]: 500, [B]: 500 } },

  // ---- exact: each amount as typed, which must add up; a person may owe zero.
  { name: 'exact 0 / 700 / 300 of Rs 10.00: a person may owe zero', method: 'exact', amountMinor: 1000, participants: [C, A, B], inputs: { [A]: 0, [B]: 700, [C]: 300 }, shares: { [A]: 0, [B]: 700, [C]: 300 } },
  { name: 'exact for one person takes everything', method: 'exact', amountMinor: 777, participants: [B], inputs: { [B]: 777 }, shares: { [B]: 777 } },
];

/** Typed values that every implementation must REFUSE, with the reason (the database answers with the code). */
export interface BadSplitVector {
  name: string;
  method: SplitMethodName;
  amountMinor: number;
  participants: string[];
  inputs: Record<string, number>;
  code: 'split_total_mismatch' | 'invalid_split_value';
}
export const BAD_SPLIT_VECTORS: BadSplitVector[] = [
  { name: 'exact amounts that fall short of the total', method: 'exact', amountMinor: 1000, participants: [A, B], inputs: { [A]: 500, [B]: 499 }, code: 'split_total_mismatch' },
  { name: 'exact amounts that go over the total', method: 'exact', amountMinor: 1000, participants: [A, B], inputs: { [A]: 500, [B]: 501 }, code: 'split_total_mismatch' },
  { name: 'percentages that add up to 99.99%', method: 'percentage', amountMinor: 1000, participants: [A, B], inputs: { [A]: 5000, [B]: 4999 }, code: 'split_total_mismatch' },
  { name: 'percentages that add up to 100.01%', method: 'percentage', amountMinor: 1000, participants: [A, B], inputs: { [A]: 5000, [B]: 5001 }, code: 'split_total_mismatch' },
  { name: 'a percentage of zero', method: 'percentage', amountMinor: 1000, participants: [A, B], inputs: { [A]: 10000, [B]: 0 }, code: 'invalid_split_value' },
  { name: 'a percentage above 100%', method: 'percentage', amountMinor: 1000, participants: [A], inputs: { [A]: 10001 }, code: 'invalid_split_value' },
  { name: 'a shares weight of zero', method: 'shares', amountMinor: 1000, participants: [A, B], inputs: { [A]: 1, [B]: 0 }, code: 'invalid_split_value' },
  { name: 'a shares weight above the limit', method: 'shares', amountMinor: 1000, participants: [A], inputs: { [A]: 1_000_001 }, code: 'invalid_split_value' },
];

// ---------------------------------------------------------------------------------------------------------------
// 2. Ledgers: a sequence of steps with the balance (paid - owed, in paise) of every member after each step.
//    A step that the database must REFUSE carries the error code; the balances then stay what they were.
// ---------------------------------------------------------------------------------------------------------------
export type VectorOp =
  | { op: 'create' | 'edit'; key: string; amount: number; payers: Record<string, number>; participants: string[]; /** absent = equal */ split?: { method: 'exact' | 'percentage' | 'shares'; values: Record<string, number> } }
  | { op: 'delete' | 'restore'; key: string }
  | { op: 'remove' | 'leave'; member: string };

export interface VectorStep {
  do: VectorOp;
  /** The error the database must answer (the step changes nothing); absent when the step succeeds. */
  error?: 'balance_not_settled' | 'former_member_balance';
  /** Net balance (paid - owed) of every member AFTER the step. */
  balances: Record<string, number>;
}

export interface LedgerVector {
  name: string;
  /** The members, by label. The first is the administrator who performs every step. */
  members: string[];
  steps: VectorStep[];
}

const bal = (a: number, b: number, c?: number, d?: number): Record<string, number> => {
  const r: Record<string, number> = { A: a, B: b };
  if (c !== undefined) r.C = c;
  if (d !== undefined) r.D = d;
  return r;
};

